(() => {
  const cols = [...document.querySelectorAll('.board-column')].map(el => ({id: el.id, dataColumn: el.dataset.columnId, header: el.querySelector('[data-column-header]')?.innerText?.trim().slice(0,40), cards: [...el.querySelectorAll('.task-board')].map(c => ({id: c.id, title: c.querySelector('[title], .task-board-title a')?.innerText?.trim()}))}));
  const heads = [...document.querySelectorAll('th')].map(th => th.innerText.trim().split('\n')[0]);
  return {heads, cols};
})()

(() => {
  const ids = [...document.querySelectorAll('[id^="board-column"]')].map(e => ({tag: e.tagName, id: e.id, cls: e.className}));
  const cards = [...document.querySelectorAll('a[href*="task_id="]')].slice(0,20).map(a => ({href: a.getAttribute('href'), text: a.innerText.trim().slice(0,40), cls: a.className}));
  const tds = [...document.querySelectorAll('td')].map(td => ({cls: td.className, id: td.id, firstText: td.innerText.trim().slice(0,30)}));
  return {ids, cards, tds};
})()

(() => {
  const cards = [...document.querySelectorAll('[data-task-id]')].map(c => ({tag: c.tagName, cls: c.className, id: c.id, tid: c.dataset.taskId, draggable: c.getAttribute('draggable'), text: c.innerText.trim().split('\n').slice(0,3).join(' | ').slice(0,80)}));
  const drops = [...document.querySelectorAll('[data-column-id]')].map(d => ({tag: d.tagName, cls: d.className, cid: d.dataset.columnId}));
  return {cards, drops};
})()

(() => {
  const card = document.querySelector('div.task-board[data-task-id="4"]');
  const parent = card?.closest('[data-column-id]');
  const lists = [...document.querySelectorAll('div.board-task-list.board-column-expanded')].map(l => ({cid: l.dataset.columnId, ids: [...l.querySelectorAll('div.task-board')].map(c => c.dataset.taskId)}));
  return {cardParentColumn: parent?.dataset.columnId, lists};
})()

(() => {
  return [...document.querySelectorAll('input, textarea, select')].map(el => {
    const lab = el.id ? document.querySelector(`label[for="${el.id}"]`)?.innerText.trim() : null;
    return {tag: el.tagName, id: el.id, name: el.name, type: el.type, label: (lab||'').slice(0,40), value: (el.value||'').slice(0,40), placeholder: el.placeholder};
  }).filter(x => /date|due/i.test(x.label + x.name + x.id + x.placeholder));
})()

(() => {
  const h2 = [...document.querySelectorAll('h2')].map(h => h.innerText.trim());
  const desc = document.querySelector('article p, .markdown p')?.innerText.trim();
  const sidebar = [...document.querySelectorAll('ul.task-summary-list, ul.no-bullet li')].map(li => li.innerText.replace(/\s+/g,' ').trim());
  const comments = [...document.querySelectorAll('.comment')].map(c => c.innerText.replace(/\s+/g,' ').trim());
  return {h2, desc, sidebar, comments};
})()

(() => {
  const card = [...document.querySelectorAll('div.task-board')].find(c => c.innerText.includes('jgkb1g60r2-n1 Bench Task'));
  const col = card?.closest('[data-column-id]');
  const colIndex = [...document.querySelectorAll('[data-column-id]')].filter(e => e.className.includes('board-column-expanded')).findIndex(e => e === col);
  const headers = [...document.querySelectorAll('th')].map(th => th.innerText.trim().split('\n')[0]);
  return {cardText: card?.innerText.replace(/\s+/g,' ').trim(), cardId: card?.dataset.taskId, columnId: col?.dataset.columnId, columnIndex, headers, tasksInCol: col ? [...col.querySelectorAll('div.task-board')].map(c => c.innerText.replace(/\s+/g,' ').trim()) : null};
})()

