(() => {
  const card = [...document.querySelectorAll('div.task-board')].find(c => c.innerText.includes('jgkb1g60r2-n1 Bench Task'));
  const col = card.closest('[data-column-id]');
  const idx = col.dataset.columnId;
  const header = document.querySelector('[class*="board-column-header-' + idx + '"]');
  const td = col.closest('td');
  const nextHeader = td?.previousElementSibling?.innerText?.trim() || td?.parentElement?.querySelector('th')?.innerText?.trim();
  return {columnId: idx, headerText: header?.innerText.trim().split('\n')[0], cellHeaderText: nextHeader?.split('\n')[0], cardHtmlId: card.id};
})()
